    low = pid.lower()
    hit = [k for k in ids if k.lower() == low or (low and low in str(pf[k].get('label', '')).lower())]
    if hit:
        return hit[0]
    if len(ids) == 1 and SINGLE_FALLBACK:
        return ids[0]
    return pid

SINGLE_FALLBACK = False

ITEMS = json.loads('{"source_var": "products", "id_field": "product_id", "noun": "product", "noun_plural": "products", "label": {"field": "type", "templates": {"credit_card": "credit card ending {card_last4}", "personal_loan": "personal loan", "car_loan": "car loan"} }, "tiers": {"field": "days_late", "list": [{"name": "standard", "min": 1, "max": 10, "limit": {"type": "business_days", "n": 10}, "ladder": [{"text": "{due_m} on {date} [or {floor_m} on {date} if the customer already said the full amount is too much; say that the remainder stays overdue]", "date": "business_days_after:3"}]}, {"name": "priority", "min": 11, "max": 45, "limit": {"type": "business_days", "n": 5}, "ladder": [{"text": "{due_m} on {date} [or {floor_m} on {date} if the customer already said the full amount is too much; say that the remainder stays overdue]", "date": "business_days_after:3"}, {"text": "{floor_m} on {date}, the deadline (say that the remainder stays overdue)", "date": "limit"}]}]}, "fields": {"due": "num(it.get(\'past_due\'))", "floor": "(((int(round(f[\'due\'] * 100)) + 1) // 2) / 100.0) if it.get(\'type\') == \'car_loan\' else first_num(it.get(by_value(it.get(\'type\'), {\'credit_card\': \'minimum_payment\', \'personal_loan\': \'instalment_amount\'}, \'\')), f[\'due\'])", "floor_spoken": "by_value(it.get(\'type\'), {\'credit_card\': \'minimum payment\', \'personal_loan\': \'instalment amount\', \'car_loan\': \'half of the overdue amount\'}, \'minimum\')", "deadline": "rule_date(T[\'limit\'], today)"}, "limit_field": "deadline", "text": "{n}. product_id {id} = \\"{label}\\". Overdue amount {due_m}, {days_late} days overdue, tier {tier}. Minimum ({floor_spoken}): {floor_m}. Acceptable amount: {floor_m} to {due_m}. Deadline (latest date): {deadline_say} ({deadline_iso}).", "ladder": {"header": "   OFFER LIST ({n} persuasion attempt{s}; each flat refusal moves to the next attempt, nothing goes in between):", "step": "     attempt {k}: {text}", "footer": "     after attempt {n} is refused: STOP, this product is refused. No other offer."}, "header": "PRODUCTS, in the order returned by get_account:", "summary": {"line": "Your {label} has an overdue amount of {due_m} and is {days_late} days overdue.", "single": "Thank you, your identity is confirmed. I am calling about overdue payments. {line} Are you able to settle this today?", "multi": "Thank you, your identity is confirmed. I am calling about overdue payments on {count} products. {lines} Are you able to settle all of them today?"}, "facts_var": "item_facts", "summary_var": "summary_line"}')
STATE = 'compute_facts_state'
