    pf = ifacts()
    ids = iids()
    pid = str(raw or '').strip()
    if pid in pf:
        return pid
    low = pid.lower()
    hit = [k for k in ids if k.lower() == low or (low and low in str(pf[k].get('label', '')).lower())]
    if hit:
        return hit[0]
    if len(ids) == 1 and SINGLE_FALLBACK:
        return ids[0]
    return pid

