        elif offers:
            k = it['refusals']
            if k < len(offers):
                msgs.append('For ' + name + ': refusals counted by code = ' + str(k) + '. If you make an offer for it now, it must be offer ' + str(k + 1) + ': ' + offers[k] + '.')
