    except Exception:
        return None
    if mon and d < today:
        try:
            d = datetime.date(y + 1, mth, day)
        except Exception:
            return None
    return d

def money(x):
    try:
        v = float(x)
    except Exception:
        return str(x)
    return '{:,.2f}'.format(v)

def num(x):
    try:
        return round(float(x), 2)
    except Exception:
        return None

def first_num(*xs):
    for x in xs:
        if num(x) is not None:
            return num(x)
    return None

def by_value(v, mapping, default=None):
    return mapping.get(str(v), default)

def load_json(v, default):
    if v is None or v == '':
        return default
    if isinstance(v, (list, dict)):
        return v
    try:
        return json.loads(v)
    except Exception:
        return default

def ledger():
    L = load_json(vars.get('ledger_json'), dict())
    if not isinstance(L, dict):
        L = dict()
    for k, dv in (('records', []), ('records_by', dict()), ('notes', []), ('fails', dict()), ('gave_up', []), ('flags', dict())):
        L.setdefault(k, dv)
    return L

def save_ledger(L):
    vars['ledger_json'] = json.dumps(L)

def ifacts():
    return load_json(vars.get('item_facts_json'), dict())

def iids():
    return load_json(vars.get('item_ids'), [])

def item_ref(raw):
    """Map whatever the model sent (an id, a label) to a known item id."""
    pf = ifacts()
    ids = iids()
    pid = str(raw or '').strip()
    if pid in pf:
        return pid
    low = pid.lower()
    hit = [k for k in ids if k.lower() == low or (low and low in str(pf[k].get('label', '')).lower())]
    if hit:
        return hit[0]
    if len(ids) == 1 and SINGLE_FALLBACK:
        return ids[0]
    return pid

SINGLE_FALLBACK = False

RULES = json.loads('[{"when": {"flag": "transfer"}, "outcome": "transferred", "reason": {"from_flag": "transfer", "map": {"restructuring": "restructuring", "general": "human"} } }, {"when": {"records": true}, "outcome": "promise"}, {"when": {"notes_all": "paid"}, "outcome": "paid", "reason": ""}, {"when": {"notes_any": true}, "from_note": {"order": "last", "skip": ["paid"], "map": {"refused": ["no_promise", "refused"], "hardship": ["no_promise", "hardship"], "dispute": ["no_promise", "dispute"], "service_error": ["no_promise", "service_error"], "paid": ["paid", ""]} } }, {"when": {"hint": "done", "gave_up": true}, "outcome": "no_promise", "reason": "service_error"}, {"when": {"hint": "done"}, "outcome": "no_promise", "reason": "refused"}]')
BY_HINT = json.loads('{"done": ["no_promise", "refused"], "transfer": ["transferred", "human"], "callback": ["not_reached", "callback"], "no_callback": ["not_reached", "no_callback"], "wrong_number": ["not_reached", "wrong_number"], "deceased": ["not_reached", "deceased"], "unclear": ["not_reached", "unclear"], "declined_pre": ["not_verified", "declined"], "declined": ["not_verified", "declined"], "failed": ["not_verified", "failed"], "account_error": ["no_promise", "service_error"]}')
NO_REASON = json.loads('["promise", "paid"]')
CLOSING = json.loads('{"lines": {"done": "Thank you for your time, [title] [last_name]. Goodbye.", "default": "Thank you for your time. Goodbye.", "transfer": "I am transferring you now. Thank you for your time, goodbye.", "callback": "Thank you, we will call back then. Goodbye.", "no_callback": "Thank you for your time. Goodbye.", "wrong_number": "I apologise for the inconvenience. Thank you, goodbye.", "deceased": "Please accept our condolences.", "unclear": "Thank you for your time. Goodbye.", "declined_pre": "I understand. Thank you for your time, goodbye.", "declined": "I understand. Thank you for your time, goodbye.", "failed": "I am sorry, I could not confirm your identity. Please contact the bank through the mobile app or a branch. Thank you, goodbye.", "account_error": "I am sorry, I cannot access your account details right now because of a technical problem. Thank you for your time, goodbye."}, "after_records": {"prefix": "A confirmation will be sent to you by text message.", "line": "done", "unless_flag": "transfer"} }')
OUT_ARG = 'outcome'
REASON_ARG = 'reason'

try:
    if vars.get('farewell_said') == 'yes':
        # the normal path already closed the call: send nothing (an empty URL never leaves the platform)
        config['url'] = ''
        raise StopIteration
    if not vars.get('close_outcome'):
        HINT = 'done' if 'done' in BY_HINT else (list(BY_HINT)[0] if BY_HINT else '')
        def count_ok(spec, L, notes, order):
            what, op, n = spec.get('of', 'records'), spec.get('op', '>='), int(spec.get('n', 1))
            if what == 'records':
                x = len(L['records'])
            elif what == 'items':
                x = len(iids())
            else:
                x = sum(1 for p in order if notes[p] == what)
            return {'>=': x >= n, '<=': x <= n, '==': x == n, '>': x > n, '<': x < n}.get(op, False)

        def match(c, L, notes, order):
            for k, v in c.items():
                if k == 'flag' and not L['flags'].get(v):
                    return False
                if k == 'records' and bool(L['records']) != bool(v):
                    return False
                if k == 'recorded_by' and not L['records_by'].get(v):
                    return False
                if k == 'gave_up' and bool(L['gave_up']) != bool(v):
                    return False
                if k == 'hint' and HINT != v:
                    return False
                if k == 'notes_any' and bool(notes) != bool(v):
                    return False
                if k == 'notes_all' and not (notes and all(notes[p] == v for p in order)):
                    return False
                if k == 'notes_none' and any(notes[p] == v for p in order):
                    return False
                if k == 'notes_with' and not any(notes[p] == v for p in order):
                    return False
                if k == 'count' and not count_ok(v, L, notes, order):
                    return False
            return True

        try:
            L = ledger()
            ids = iids()
            notes = dict((n[0], n[1]) for n in L['notes'])
            order = [p for p in ids if p in notes] + [p for p in notes if p not in ids]
            out, why = BY_HINT.get(HINT, ['', ''])
            for R in RULES:
                if not match(R['when'], L, notes, order):
                    continue
                if 'from_note' in R:
                    FN = R['from_note']
                    skip = FN.get('skip', [])
                    cand = [p for p in order if notes[p] not in skip]
                    if not cand:
                        continue
                    if FN.get('priority'):
                        pick = sorted(cand, key=lambda p: (FN['priority'].index(notes[p]) if notes[p] in FN['priority'] else 99, order.index(p)))[0]
                    elif FN.get('order') == 'last':
                        pick = cand[-1]
                    else:
                        pick = cand[0]
                    out, why = FN['map'].get(notes[pick], [R.get('outcome', ''), notes[pick]])
                else:
                    out = R['outcome']
                    rs = R.get('reason', '')
                    if isinstance(rs, dict):
                        val = L['flags'].get(rs['from_flag'], '')
                        why = rs.get('map', dict()).get(val, val)
                    else:
                        why = rs
                break
            vars['close_outcome'] = out
            if why and out not in NO_REASON:
                vars['close_reason'] = why
            line = CLOSING['lines'].get(HINT, CLOSING['lines'].get('default', ''))
            AR = CLOSING.get('after_records')
            if AR and L['records'] and not L['flags'].get(AR.get('unless_flag', '')):
                line = AR['prefix'] + ' ' + CLOSING['lines'].get(AR['line'], line)
            line = re.sub(r'\[(\w+)\]', lambda m: str(vars.get(m.group(1)) or ''), line)
            vars['closing_line'] = ' '.join(line.split())
        except Exception as ex:
            vars['close_outcome'] = BY_HINT.get(HINT, ['', ''])[0]
            if BY_HINT.get(HINT, ['', ''])[1]:
                vars['close_reason'] = BY_HINT.get(HINT, ['', ''])[1]
            vars['closing_line'] = CLOSING['lines'].get('default', '')
    b = config.get('body') or dict()
    b[OUT_ARG] = vars.get('close_outcome') or ''
    if REASON_ARG:
        if vars.get('close_reason') and vars.get('close_outcome') not in NO_REASON:
            b[REASON_ARG] = vars.get('close_reason')
        else:
            b.pop(REASON_ARG, None)
    config['body'] = b
except StopIteration:
    pass
except Exception:
    pass
